import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────────────
  // 1. GEOMETRY & MATERIAL
  // ─────────────────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(2.4, 1.5);

  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
  });

  // ─────────────────────────────────────────────────────────────────────────
  // 2. LOAD TEXTURE
  // ─────────────────────────────────────────────────────────────────────────
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = THREE.SRGBColorSpace;
      material.colorNode = texture;
      material.needsUpdate = true;
    });
  }

  const mesh = new THREE.Mesh(geometry, material);

  // ─────────────────────────────────────────────────────────────────────────
  // 3. SCENE PLACEMENT
  // ─────────────────────────────────────────────────────────────────────────
  if (config.scenePosition) {
    const [x, y, z] = config.scenePosition;
    mesh.position.set(x, y, z);
  }

  // ─────────────────────────────────────────────────────────────────────────
  // 4. INTERACTION STATE
  // ─────────────────────────────────────────────────────────────────────────
  let hoverTimeline = null;
  let pressTimeline = null;
  const initialPosition = mesh.position.clone();

  const handlers = {
    onPointerEnter() {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(mesh.position, {
        y: initialPosition.y + 0.15,
        duration: 0.5,
        ease: 'power3.out',
      });
    },
    onPointerLeave() {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(mesh.position, {
        y: initialPosition.y,
        duration: 0.5,
        ease: 'power3.out',
      });
    },
    onPointerDown() {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp() {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(mesh.scale, {
        x: 1,
        y: 1,
        duration: 0.3,
        ease: 'back.out',
      });
    },
    onClick() {
      ctx.emit('hub-journal.select', { cardIndex: 2 });
    },
  };

  // ─────────────────────────────────────────────────────────────────────────
  // 5. STOCK BADGE (data binding)
  // ─────────────────────────────────────────────────────────────────────────
  mesh.userData.stockBadge = null;
  mesh.userData.inStock = true;

  // ─────────────────────────────────────────────────────────────────────────
  // 6. CLEANUP
  // ─────────────────────────────────────────────────────────────────────────
  mesh.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geometry.dispose();
    material.dispose();
  };

  mesh.userData.handlers = handlers;

  return mesh;
}
